-- extended-master-seed.sql — 本番には入れないマスタ。
--
-- migration はどの DB にも同じように適用されるので、「本番には要らないが
-- 開発／撮影用 DB には欲しい」データは migration に置けない。ここに置く。
--   素材（904 件・Excel 由来 — 品目 app.items の MATERIAL 行）/ 拠点 /
--   不良種類 / 承認グループ・承認フロー
--
-- 本番はこれらを運用に合わせて画面から作る。dev は現行 DB のスナップショットを
-- 復元するので実データが入る。撮影用 DB は tools/docs-screenshots が流す。
--
-- 適用（新規 DB に 1 回だけ）:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f sql/extended-master-seed.sql

BEGIN;
SET session_replication_role = replica;
-- app.approval_groups


-- app.approval_flows


-- app.approval_flow_steps


-- app.plants


-- app.defect_types


-- app.items（素材）— 旧 app.materials。品目統合の第 3 段で旧表が消えたので
-- 品目へ直に入れる。id は旧 materials.id をそのまま使う（新しい DB では
-- items が空なので衝突しない）。


-- ─── 連番の採番位置を合わせる ────────────────────────────────────────────────
-- 上の INSERT は id を明示して入れている。明示 id の INSERT はシーケンスを
-- 進めないので、このあと画面や別のシードが id を省略して INSERT すると
-- 1 番から採番し直して重複で落ちる（撮影用 DB で実際に
-- manufacturing-demo-seed が approval_groups で落ちていた）。
-- 入れ終わった時点の最大値までシーケンスを送っておく。
SELECT setval(
  pg_get_serial_sequence('app.approval_groups', 'id'),
  GREATEST((SELECT COALESCE(MAX(id), 0) FROM app.approval_groups), 1)
);
SELECT setval(
  pg_get_serial_sequence('app.approval_flow_steps', 'id'),
  GREATEST((SELECT COALESCE(MAX(id), 0) FROM app.approval_flow_steps), 1)
);
SELECT setval(
  pg_get_serial_sequence('app.defect_types', 'id'),
  GREATEST((SELECT COALESCE(MAX(id), 0) FROM app.defect_types), 1)
);
SELECT setval(
  pg_get_serial_sequence('app.plants', 'id'),
  GREATEST((SELECT COALESCE(MAX(id), 0) FROM app.plants), 1)
);
-- 品目（素材 904 件を明示 id で入れた）。これを送っておかないと、あとから
-- 画面や別のシードが品目を作るときに 1 番から採り直して衝突する。
SELECT setval(
  pg_get_serial_sequence('app.items', 'id'),
  GREATEST((SELECT COALESCE(MAX(id), 0) FROM app.items), 1)
);

SET session_replication_role = DEFAULT;
COMMIT;
